StructuredText.Text:
// The same OB fires for a station leaving and for it returning. Event_Class is what tells
// them apart, and getting this backwards would set the fault flag on recovery and clear it
// on failure - a system that reports healthy precisely when it is not:
//     16#39  incoming event - the station has just failed
//     16#38  outgoing event - the station has come back
#lost := (#Event_Class = B#16#39);
#id := #LADDR;

// Identifiers live in Diag_DB rather than as literals here, so re-adding a station in TIA -
// which reassigns them - is a data change instead of an SCL edit and a redownload.
IF #id = "Diag_DB".Laddr_AFT THEN
    "Diag_DB".AftLost := #lost;
    IF #lost THEN
        "Diag_DB".AftLossCount := "Diag_DB".AftLossCount + 1;
    END_IF;

ELSIF #id = "Diag_DB".Laddr_MID THEN
    "Diag_DB".MidLost := #lost;
    IF #lost THEN
        "Diag_DB".MidLossCount := "Diag_DB".MidLossCount + 1;
    END_IF;

ELSIF #id = "Diag_DB".Laddr_FWD THEN
    "Diag_DB".FwdLost := #lost;
    IF #lost THEN
        "Diag_DB".FwdLossCount := "Diag_DB".FwdLossCount + 1;
    END_IF;

ELSE
    // An identifier matching none of the three. Recorded rather than dropped: it means either
    // the identifiers were reassigned and Diag_DB was not updated, or a device is on the
    // network that this block does not know about. Silently ignoring it would hide a real
    // station failure, which is the exact failure this block was written to prevent.
    "Diag_DB".UnknownLost := #lost;
    "Diag_DB".LastUnknownLaddr := #id;
END_IF;

// One bit for the HMI to watch instead of ORing four.
"Diag_DB".AnyStationLost := "Diag_DB".AftLost
                          OR "Diag_DB".MidLost
                          OR "Diag_DB".FwdLost
                          OR "Diag_DB".UnknownLost;
